import {payrollBenefits,employerMatch,insuranceClaim} from './benefit-calculations.js';
const field=(label,key,value,min,max,step=1)=>`<label class="field"><span>${label}</span><input type="number" data-value="${key}" aria-label="${label}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const slider=(label,key,value,min,max,step=1,suffix='%')=>`<label class="range-field"><span>${label}<strong>${value}${suffix}</strong></span><input type="range" data-value="${key}" aria-label="${label}" value="${value}" min="${min}" max="${max}" step="${step}"><small>${min}${suffix}<span>${max}${suffix}</span></small></label>`;
export const benefitSources=[
{id:'benefit-cpp-2026',title:'CPP contribution rates, maximums and exemptions',publisher:'Canada Revenue Agency',url:'https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/payroll/payroll-deductions-contributions/canada-pension-plan-cpp/cpp-contribution-rates-maximums-exemptions.html',reviewedAt:'2026-10-24'},
{id:'benefit-cpp2-2026',title:'Second additional CPP contribution rates and maximums',publisher:'Canada Revenue Agency',url:'https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/payroll/calculating-deductions/making-deductions/second-additional-cpp-contribution-rates-maximums.html',reviewedAt:'2026-10-24'},
{id:'benefit-ei-2026',title:'EI premium rates and maximums',publisher:'Canada Revenue Agency',url:'https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/payroll/payroll-deductions-contributions/employment-insurance-ei/ei-premium-rates-maximums.html',reviewedAt:'2026-10-24'},
{id:'benefit-plan-tax',title:'Contributions to savings and pension plans',publisher:'Canada Revenue Agency',url:'https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/payroll/benefits-allowances/benefits-allowances-chart/saving-pensions.html',reviewedAt:'2026-10-24'}];
export function renderBenefitActivity(name,a,money){money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2,minimumFractionDigits:2}).format(n);
if(name==='payroll'){
 const salary=a.salary??80000,r=payrollBenefits(salary);
 return `<div class="activity"><div class="activity-head"><strong>What are these paycheque deductions?</strong><span>2026 · Outside Quebec</span></div><div class="activity-content"><p class="lab-prompt">CPP and EI are statutory public programs, not optional extras your employer invented. Change annual pay to see where contribution ceilings apply.</p>${field('Annual pensionable and insurable pay ($)','salary',salary,0,1000000)}<div class="benefit-results" aria-live="polite"><div class="table-scroll"><table><thead><tr><th>2026 annual estimate</th><th>You contribute</th><th>Employer contributes</th></tr></thead><tbody><tr><th>CPP base + first additional</th><td>${money(r.cpp)}</td><td>${money(r.cpp)}</td></tr><tr><th>CPP2 second additional</th><td>${money(r.cpp2)}</td><td>${money(r.cpp2)}</td></tr><tr><th>Employment Insurance</th><td>${money(r.ei)}</td><td>${money(r.employerEI)}</td></tr><tr><th>Total statutory premiums</th><td>${money(r.employee)}</td><td>${money(r.employer)}</td></tr></tbody></table></div><div class="stats"><div class="stat">Your annual CPP + CPP2<strong>${money(r.cpp+r.cpp2)}</strong></div><div class="stat">Your annual EI<strong>${money(r.ei)}</strong></div><div class="stat good">Pay after these premiums<strong>${money(r.beforeTax)}</strong><span>Before income tax and other deductions</span></div></div><div class="lab-insight"><strong>This is not take-home pay.</strong><p>Income tax, optional plan deductions, union dues and other adjustments are excluded. Your employer’s contribution is not subtracted from your salary again, and it is not a personal account balance you can withdraw.</p></div></div><details class="notes"><summary>2026 rules used in this model</summary><p>CPP employee rate 5.95% on annual pensionable pay above $3,500 up to $74,600 (maximum $4,230.45). CPP2 4% on pay between $74,600 and $85,000 (maximum $416). Employer matches CPP components. EI employee rate 1.63% up to $68,900 (maximum $1,123.07). Standard employer EI premium is 1.4 times the employee amount; approved reduced rates may differ. Full-year single-employer example with standard coverage and no age-related exemptions. Quebec uses QPP and different EI/QPIP rules. This does not estimate EI entitlement or your future pension.</p></details></div></div>`;
}
if(name==='matching'){
 const salary=a.salary??80000,employeePercent=a.employeePercent??5,matchPercent=a.matchPercent??50,eligiblePercent=a.eligiblePercent??6,r=employerMatch(salary,employeePercent,matchPercent,eligiblePercent);
 return `<div class="activity"><div class="activity-head"><strong>Decode the employer match</strong><span>Fictional plan terms</span></div><div class="activity-content"><p class="lab-prompt">“We match 50% of your contributions on the first 6% of salary.” That is a maximum employer contribution of 3% of salary—not a 50% investment return on every dollar you own.</p>${field('Annual eligible salary ($)','salary',salary,0,1000000)}${slider('Your contribution as % of salary','employeePercent',employeePercent,0,20,.5)}${slider('Employer match as % of eligible contribution','matchPercent',matchPercent,0,100,5)}${slider('Salary percentage eligible for matching','eligiblePercent',eligiblePercent,0,15,.5)}<div class="benefit-results" aria-live="polite"><div class="stats"><div class="stat">Your annual contribution<strong>${money(r.employee)}</strong></div><div class="stat good">Employer’s annual match<strong>${money(r.employer)}</strong></div><div class="stat">Combined annual deposit<strong>${money(r.total)}</strong></div></div><div class="lab-insight"><strong>${r.unclaimedMatch>0?money(r.unclaimedMatch)+' of the model match remains unused.':'You reach the model’s full available match.'}</strong><p>${r.additionalEmployee>0?'An additional '+money(r.additionalEmployee)+' employee contribution reaches the illustrated match threshold.':'Contributing above the matching threshold adds your own savings but no extra employer match under these terms.'} Check affordability, plan eligibility, vesting, fees and access before making a decision.</p></div></div><p class="fineprint">Employer deposit = min(your annual contribution, salary × eligible salary %) × match %. No investment growth or tax is calculated. Different plans use different formulas and vesting rules. A group RRSP uses RRSP room for eligible employee and employer contributions; pension/DPSP arrangements can create a pension adjustment affecting later RRSP room. Employer group-RRSP contributions are generally taxable employment benefits with a possible offsetting RRSP deduction when eligible. Do not assume all employer plans use the same tax treatment.</p></div></div>`;
}
if(name==='insurance'){
 const bill=a.bill??1200,eligible=a.eligible??1200,deductible=a.deductible??100,coveragePercent=a.coveragePercent??80,remainingMax=a.remainingMax??1000,r=insuranceClaim(bill,eligible,deductible,coveragePercent,remainingMax);
 return `<div class="activity"><div class="activity-head"><strong>Covered does not always mean free</strong><span>Fictional extended-health claim</span></div><div class="activity-content"><p class="lab-prompt">Compare the bill, eligible amount, deductible, coverage percentage and remaining annual maximum. Try a larger bill: where does the insurer stop paying?</p>${field('Total provider bill ($)','bill',bill,0,100000)}${field('Amount recognized as eligible ($)','eligible',eligible,0,100000)}${field('Deductible still unpaid ($)','deductible',deductible,0,10000)}${slider('Insurer coverage after deductible','coveragePercent',coveragePercent,0,100,5)}${field('Remaining annual insurer benefit maximum ($)','remainingMax',remainingMax,0,100000)}<div class="benefit-results" aria-live="polite"><div class="stats"><div class="stat good">Insurer pays<strong>${money(r.insurer)}</strong></div><div class="stat warn">You pay<strong>${money(r.outOfPocket)}</strong></div><div class="stat">Benefit maximum left<strong>${money(r.remainingMax)}</strong></div></div><div class="lab-insight"><strong>The policy wording decides.</strong><p>In this model, ${money(r.eligibleAmount)} is eligible, ${money(r.usedDeductible)} meets the outstanding deductible, then ${coveragePercent}% coverage applies up to the remaining insurer-payment maximum. Ineligible charges stay with you.</p></div></div><p class="fineprint">Simplified single-claim model: insurer pays min(max(0, min(bill, eligible amount) − remaining deductible) × coverage %, remaining benefit maximum). Real plans may use fee guides, per-service limits, different deductibles, coordination with a partner’s plan, exclusions and pre-authorization. This is not a quote or assessment of medical necessity. Check whether premiums and claims are taxable under your plan and province.</p></div></div>`;
}
return null;
}
